/* Notion DNA — paper white, ink gray, serif calm, tool that disappears */
.theme-notion-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0.004 91.4);
  --surface-2: oklch(0.949 0.005 95.1);
  --fg: oklch(0.213 0 0);
  --fg-muted: oklch(0.569 0.005 91.5);
  --accent: oklch(0.606 0.167 252.7);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.659 0.159 55.7);
  --line: oklch(0.933 0.003 106.5);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.645 0.185 25.9);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Spectral", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.03em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-notion-dna h1,
.theme-notion-dna h2,
.theme-notion-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-notion-dna h1 { font-weight: 600; }
.theme-notion-dna button { font-weight: 500; }
.theme-notion-dna a { text-decoration: underline; text-decoration-color: var(--line); text-underline-offset: 3px; }
.theme-notion-dna ::selection { background: oklch(0.85 0.06 240 / 60%); }

/* depth */
.theme-notion-dna table { border-collapse: collapse; }
.theme-notion-dna th, .theme-notion-dna td { border: 1px solid var(--line); }
.theme-notion-dna thead th { background: var(--surface); color: var(--fg-muted); font-weight: 500; font-size: 0.8125rem; }
.theme-notion-dna tbody tr:hover { background: color-mix(in oklab, var(--surface) 70%, transparent); }
.theme-notion-dna input, .theme-notion-dna select, .theme-notion-dna textarea { background: var(--bg); border: 1px solid var(--line); transition: border-color 100ms ease, box-shadow 100ms ease; }
.theme-notion-dna input:focus-visible, .theme-notion-dna select:focus-visible, .theme-notion-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 2px color-mix(in oklab, var(--accent) 25%, transparent); }
.theme-notion-dna kbd { font-size: 0.75em; background: var(--surface); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: 3px; padding: 0.1em 0.4em; color: var(--fg-muted); }
.theme-notion-dna a:hover { background: var(--surface-2); }
.theme-notion-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-notion-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-notion-dna ::-webkit-scrollbar-thumb { background: oklch(0.85 0.005 95); border-radius: var(--radius-pill); }
.theme-notion-dna ::-webkit-scrollbar-thumb:hover { background: oklch(0.75 0.005 95); }
.theme-notion-dna .label-caps { font-size: 0.6875rem; color: var(--fg-muted); letter-spacing: 0.04em; }
.theme-notion-dna .themed-border { border-color: var(--line); }
.theme-notion-dna button { transition: background 100ms ease; }
.theme-notion-dna button:active { background: var(--surface-2); }
.theme-notion-dna hr { border-color: var(--line); }

/* alt mode: Notion dark — warm charcoal #191919, soft gray ink */
.theme-notion-dna.alt-mode {
  --bg: oklch(0.215 0 0);
  --surface: oklch(0.255 0 0);
  --surface-2: oklch(0.295 0 0);
  --fg: oklch(0.880 0.005 95);
  --fg-muted: oklch(0.620 0.005 95);
  --line: oklch(1 0 0 / 10%);
  --accent: oklch(0.660 0.130 250);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-notion-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.4 0 0); }
.theme-notion-dna.alt-mode ::selection { background: oklch(0.5 0.1 250 / 45%); }
.theme-notion-dna.alt-mode a { text-decoration-color: oklch(1 0 0 / 25%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
